[SrsReportParameterAttribute(classStr(METPickupAdviceContract))]
public class METPickupAdviceDP extends SRSReportDataProviderBase
{
    // Work-in-progress, place holder values used.

    METPickupAdviceLinesTmp         linesTmp;
    METPickupAdviceHeaderTmp        headerTmp;
    METPickupAdviceReasonsTmp       reasonsTmp;

}

Method.Source:
    public void processReport()
    {
        CustParameters  custParams = CustParameters::find();
        CompanyInfo     companyInfo = CompanyInfo::find();

        SalesTable  salesTable;
        SalesLine   salesLine;
        select firstonly salesTable;    // ****

        headerTmp.RMANumber                 = salesTable.SalesId;
        headerTmp.DocumentDate              = today();
        headerTmp.CustomerABN               = '99999';
        headerTmp.CustomerAccountNumber     = salesTable.CustAccount;
        headerTmp.ClaimNumber               = 'CLM999999';
        headerTmp.ClaimDate                 = today();
        headerTmp.Contact                   = '0419999999';
        headerTmp.InvoiceNumber             = salesTable.SalesId;   // ****
        headerTmp.InvoiceDate               = today();
        headerTmp.CompanyName               = companyInfo.name();
        headerTmp.CompanyABN                = 'ABN: ' + companyInfo.CoRegNum;
        headerTmp.CompanyAddress            = companyInfo.postalAddress().Address;
        headerTmp.Barcode1                  = "4827349827343223";
        headerTmp.Barcode2                  = "423894729384723987";

        InventLocation inventLocation = InventLocation::find(salesTable.InventLocationId);        

        headerTmp.PickupName                = inventLocation.Name;
        headerTmp.PickupAddress             = inventLocation.address();

        headerTmp.CustomerConditionsText    = custParams.METPickupAdviceCustomerConditions;
        headerTmp.StaffInstructionsText     = custParams.METPickupAdviceStaffInstructions;
        headerTmp.CompanyLogo               = CustTable::metGetCustReportLogo(salesTable.CustAccount).getData();

        headerTmp.insert();

        while select salesLine
            where   salesLine.SalesId   == salesTable.SalesId
        {
            linesTmp.clear();
            linesTmp.ItemId         = salesLine.ItemId;
            linesTmp.ItemName       = salesLine.Name;   // **
            linesTmp.PackQty        = salesLine.SalesQty;
            linesTmp.SlotNumber     = 'A99999';
            linesTmp.ReasonCode     = '999';
            linesTmp.insert();
        }

        this.addReasonCodes();
    }

    public void addReasonCodes()
    {
        void _add(str _code, str _name)
        {
            reasonsTmp.clear();
            reasonsTmp.Code     = _code;
            reasonsTmp.Name     = _name;
            reasonsTmp.insert();
        }

        // TODO, select from table when defined.

        _add('11',      'Obsolete');
        _add('21',      'Defective');
        _add('22',      'Dead on arrival');
        _add('31',      'Order clerk ordering error');
        _add('39',      'Wrong quantity');
        _add('52',      'Needs service/maintenance');
        _add('53',      'Recall');
    }

[SrsReportDataSet(tableStr(METPickupAdviceLinesTmp))]
public METPickupAdviceLinesTmp getLinesTmp()
{
    select linesTmp;
    return linesTmp;
}

[SrsReportDataSet(tableStr(METPickupAdviceHeaderTmp))]
public METPickupAdviceHeaderTmp getHeaderTmp()
{
    select headerTmp;
    return headerTmp;
}

[SrsReportDataSet(tableStr(METPickupAdviceReasonsTmp))]
public METPickupAdviceReasonsTmp getReasonsTmp()
{
    select reasonsTmp;
    return reasonsTmp;            
}
